namespace rathena::server_core {
class Core{
private:
	e_core_status m_status;
	e_core_type m_type;
	bool m_run_once;
	bool m_crashed;

protected:
	virtual bool initialize( int32 argc, char* argv[] );
	virtual void handle_main( t_tick next );
	virtual void finalize();
	virtual void handle_crash();
	virtual void handle_shutdown();
	void set_status( e_core_status status );

public:
	Core( e_core_type type ){
		this->m_status = e_core_status::NOT_STARTED;
		this->m_run_once = false;
		this->m_crashed = false;
		this->m_type = type;
	}

	e_core_status get_status();
	e_core_type get_type();
	bool is_running();
	// TODO: refactor to protected
	void set_run_once( bool run_once );
	void signal_crash();
	void signal_shutdown();
	int32 start( int32 argc, char* argv[] );
};
}

class YamlDatabase{
// Internal stuff
private:
	std::string type;
	uint16 version;
	uint16 minimumVersion;
	std::string currentFile;
	bool shouldLoadGenerator{false};

	bool verifyCompatibility( const ryml::Tree& rootNode );
	bool load( const std::string& path );
	void parse( const ryml::Tree& rootNode );
	void parseImports( const ryml::Tree& rootNode );
	template <typename R> bool asType( const ryml::NodeRef& node, const std::string& name, R& out );

// These should be visible/usable by the implementation provider
protected:
	ryml::Parser parser;

	// Helper functions
	bool nodeExists( const ryml::NodeRef& node, const std::string& name );
	bool nodesExist( const ryml::NodeRef& node, std::initializer_list<const std::string> names );
	int32 getLineNumber(const ryml::NodeRef& node);
	int32 getColumnNumber(const ryml::NodeRef& node);
	void invalidWarning( const ryml::NodeRef& node, const char* fmt, ... );
	std::string getCurrentFile();

	// Conversion functions
	bool asBool(const ryml::NodeRef& node, const std::string &name, bool &out);
	bool asInt16(const ryml::NodeRef& node, const std::string& name, int16& out );
	bool asUInt16(const ryml::NodeRef& node, const std::string& name, uint16& out);
	bool asInt32(const ryml::NodeRef& node, const std::string &name, int32 &out);
	bool asUInt32(const ryml::NodeRef& node, const std::string &name, uint32 &out);
	bool asInt64(const ryml::NodeRef& node, const std::string &name, int64 &out);
	bool asUInt64(const ryml::NodeRef& node, const std::string &name, uint64 &out);
	bool asFloat(const ryml::NodeRef& node, const std::string &name, float &out);
	bool asDouble(const ryml::NodeRef& node, const std::string &name, double &out);
	bool asString(const ryml::NodeRef& node, const std::string &name, std::string &out);
	bool asUInt16Rate(const ryml::NodeRef& node, const std::string& name, uint16& out, uint16 maximum=10000);
	bool asUInt32Rate(const ryml::NodeRef& node, const std::string& name, uint32& out, uint32 maximum=10000);

	void setGenerator(bool shouldLoad);

	virtual void loadingFinished();

public:
	YamlDatabase( const std::string& type_, uint16 version_, uint16 minimumVersion_ ){
		this->type = type_;
		this->version = version_;
		this->minimumVersion = minimumVersion_;
	}

	YamlDatabase( const std::string& type_, uint16 version_ ) : YamlDatabase( type_, version_, version_ ){
		// Empty since everything is handled by the real constructor
	}

	bool load();
	bool reload();

	// Functions that need to be implemented for each type
	virtual void clear() = 0;
	virtual const std::string getDefaultLocation() = 0;
	virtual uint64 parseBodyNode( const ryml::NodeRef& node ) = 0;
};

typedef enum DBRelease {
	DB_RELEASE_NOTHING = 0x0,
	DB_RELEASE_KEY     = 0x1,
	DB_RELEASE_DATA    = 0x2,
	DB_RELEASE_BOTH    = DB_RELEASE_KEY|DB_RELEASE_DATA,
} DBRelease;

typedef enum DBType {
	DB_INT,
	DB_UINT,
	DB_STRING,
	DB_ISTRING,
	DB_INT64,
	DB_UINT64,
} DBType;

typedef enum DBOptions {
	DB_OPT_BASE            = 0x00,
	DB_OPT_DUP_KEY         = 0x01,
	DB_OPT_RELEASE_KEY     = 0x02,
	DB_OPT_RELEASE_DATA    = 0x04,
	DB_OPT_RELEASE_BOTH    = DB_OPT_RELEASE_KEY|DB_OPT_RELEASE_DATA,
	DB_OPT_ALLOW_NULL_KEY  = 0x08,
	DB_OPT_ALLOW_NULL_DATA = 0x10,
} DBOptions;

typedef union DBKey {
	int32 i;
	uint32 ui;
	const char *str;
	int64 i64;
	uint64 ui64;
} DBKey;

typedef enum DBDataType {
	DB_DATA_INT,
	DB_DATA_UINT,
	DB_DATA_PTR,
	DB_DATA_I64
} DBDataType;

typedef struct DBData {
	DBDataType type;
	union {
		int32 i;
		uint32 ui;
		void *ptr;
		int64 i64;
	} u;
} DBData;

struct DBIterator
{
	DBData* (*first)(DBIterator* self, DBKey* out_key);
	DBData* (*last)(DBIterator* self, DBKey* out_key);
	DBData* (*next)(DBIterator* self, DBKey* out_key);
	DBData* (*prev)(DBIterator* self, DBKey* out_key);
	bool (*exists)(DBIterator* self);
	int32 (*remove)(DBIterator* self, DBData *out_data);
	void (*destroy)(DBIterator* self);
};

struct DBMap {
	DBIterator* (*iterator)(DBMap* self);
	bool (*exists)(DBMap* self, DBKey key);
	DBData* (*get)(DBMap* self, DBKey key);
	uint32 (*getall)(DBMap* self, DBData** buf, uint32 max, DBMatcher match, ...);
	uint32 (*vgetall)(DBMap* self, DBData** buf, uint32 max, DBMatcher match, va_list args);
	DBData* (*ensure)(DBMap* self, DBKey key, DBCreateData create, ...);
	DBData* (*vensure)(DBMap* self, DBKey key, DBCreateData create, va_list args);
	int32 (*put)(DBMap* self, DBKey key, DBData data, DBData *out_data);
	int32 (*remove)(DBMap* self, DBKey key, DBData *out_data);
	int32 (*foreach)(DBMap* self, DBApply func, ...);
	int32 (*vforeach)(DBMap* self, DBApply func, va_list args);
	int32 (*clear)(DBMap* self, DBApply func, ...);
	int32 (*vclear)(DBMap* self, DBApply func, va_list args);
	int32 (*destroy)(DBMap* self, DBApply func, ...);
	int32 (*vdestroy)(DBMap* self, DBApply func, va_list args);
	uint32 (*size)(DBMap* self);
	DBType (*type)(DBMap* self);
	DBOptions (*options)(DBMap* self);
};

